package com.malevolentgods.fourtwenty.domain;

/**
 * Terpene and hemp colours (RGB), in {@link Terpenes} order. Generated by
 * tools/generate_terpenes.py from tools/terpenes.json; don't edit by hand.
 */
public final class TerpenePalette {
    private TerpenePalette() {}

    /** Natural Hemp. */
    public static final int NATURAL = 0xC9B98F;

    private static final int[] BASES = {0x6B5A4C, 0xC98A12, 0x2F7A47, 0x6E59A8};

    /** Each accord's colour: its row's bright tone. */
    private static final int[] ACCORDS = {
            0xB8A897, 0xE8D7B0, 0xC9C9C7, 0xB7C0C8, 0xA0673A, 0xF2C80F, 0xD7262E, 0xF07F1A,
            0x8C8C2E, 0x9BD42A, 0x2EAA4A, 0x17A398, 0x8A3FD1, 0xF05AA0, 0x2F6BE0, 0x2BB5E8,
    };

    private static final int[] FINALS = {
            0xE6DDD2, 0xB8A897, 0x7E6F62, 0x3B322C, 0xF6EEDB, 0xE8D7B0, 0xA89A7A, 0x4A4336,
            0xF7F7F5, 0xC9C9C7, 0x808080, 0x1C1C1E, 0xEEF2F5, 0xB7C0C8, 0x5F6B76, 0x252B33,
            0xD9B99B, 0xA0673A, 0x7A5A44, 0x4A2E1E, 0xF8EBA6, 0xF2C80F, 0xBFA14A, 0x8A6A0E,
            0xF2B8B0, 0xD7262E, 0x9E4A4A, 0x6B1018, 0xF9CFA8, 0xF07F1A, 0xB8703F, 0x8A3A0E,
            0xD8D9B0, 0x8C8C2E, 0x6E6E4A, 0x3F4022, 0xE2F5B5, 0x9BD42A, 0x87A05A, 0x4E6E14,
            0xBFE6C4, 0x2EAA4A, 0x5E8A68, 0x1C4A2A, 0xB8E8E0, 0x17A398, 0x4E8A86, 0x0E4A4A,
            0xDCCDF0, 0x8A3FD1, 0x7A6890, 0x3A1A5C, 0xF9D5E5, 0xF05AA0, 0xB07A90, 0x7A1E4A,
            0xC5D9F5, 0x2F6BE0, 0x5A7095, 0x1A2A6B, 0xCFEFFA, 0x2BB5E8, 0x6A9AAE, 0x12506E,
    };

    /** The Minecraft-colour terpenes, in DyeColor order. */
    private static final int[] MINECRAFT = {
            0xFDFDFD, 0xFF7D00, 0xD652DB, 0x31B9F3, 0xFFE700, 0x87C03C, 0xED889F, 0x525252,
            0x9E9F9E, 0x00A7AC, 0x8036CB, 0x293FCB, 0x7C5337, 0x61811A, 0xB02522, 0x1E1C1D,
    };

    /** A Minecraft-colour terpene's colour (the colour caught in the Infuser). */
    public static int minecraft(net.minecraft.world.item.DyeColor dye) { return MINECRAFT[dye.getId()]; }

    /** A terpene's colour (a final terpene's is its hemp colour). */
    public static int color(Terpenes.Code code) {
        return switch (code.tier()) {
            case 1 -> BASES[code.index()];
            case 2 -> ACCORDS[code.index()];
            default -> FINALS[code.index()];
        };
    }
}
